// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(1000000, "Token", "TKN");
    }

    function testFuzz_property(uint256 burnAmount) public {
        uint256 ownerBalance = c.balanceOf(address(this));
        vm.assume(burnAmount <= ownerBalance);
        vm.assume(burnAmount > 0);

        c.burn(burnAmount);

        uint256 sumBalances = c.balanceOf(address(this));

        assertEq(c.totalSupply(), sumBalances);
    }
}
